// B1 migration: blog markdown must be readable at runtime on Cloudflare Workers,
// which have NO `node:fs` / `process.cwd()`. This script pre-reads every post from
// src/content/blog at build/dev time and inlines the raw bodies into a TS module
// (src/lib/blogContent.generated.ts) that is bundled with the Worker. Run from
// scripts/build.sh, scripts/dev.sh and the `deploy`/`preview` npm scripts so the
// generated file is always fresh.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");
const dir = path.join(root, "src", "content", "blog");

const files = readdirSync(dir).filter((f) => f.endsWith(".md"));
const map = {};
for (const f of files) {
  map[f] = readFileSync(path.join(dir, f), "utf8");
}

const out =
  "// AUTO-GENERATED by scripts/gen-blog-content.mjs — do NOT edit by hand.\n" +
  "// Regenerated on every build/dev (see scripts/build.sh, dev.sh, package.json).\n" +
  "export const BLOG_CONTENT: Record<string, string> = " +
  JSON.stringify(map, null, 2) +
  ";\n";

writeFileSync(path.join(root, "src", "lib", "blogContent.generated.ts"), out, "utf8");
console.log(`[gen-blog-content] inlined ${files.length} blog posts -> src/lib/blogContent.generated.ts`);
